code.cpp:
class Solution {
public:
    char processStr(string s, long long k) {
        int n = s.size();
        vector<long long> len(n + 1, 0);
        for (int i = 0; i < n; i++) {
            char c = s[i];
            if (c == '*') len[i + 1] = len[i] > 0 ? len[i] - 1 : 0;
            else if (c == '#') len[i + 1] = len[i] * 2;
            else if (c == '%') len[i + 1] = len[i];
            else len[i + 1] = len[i] + 1;
        }
        if (k >= len[n]) return '.';
        for (int i = n - 1; i >= 0; i--) {
            char c = s[i];
            long long prev = len[i];
            if (c == '*') {
                // removal of last char: index k unchanged
            } else if (c == '%') {
                k = prev - 1 - k;
            } else if (c == '#') {
                if (k >= prev) k -= prev;
            } else {
                if (k == prev) return c;
            }
        }
        return '.';
    }
};
